//! Launcher dialog for executables: run inside the desktop terminal, run
//! detached in its own OS window, or configure arguments first through a
//! form auto-generated by parsing the program's --help output (recursively
//! through subcommands).

use std::path::PathBuf;
use std::process::Command;
use std::sync::mpsc;
use std::time::Duration;

use ratatui::crossterm::event::{KeyCode, KeyEvent, MouseButton, MouseEvent, MouseEventKind};
use ratatui::layout::Rect;
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::Paragraph;
use ratatui::Frame;

use super::pin::{PinTo, PinnedApp};
use super::{Action, AppWindow, Launch};

const SPINNER: [&str; 10] = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];

#[derive(Clone)]
struct HelpOpt {
    flag: String,
    takes_value: bool,
    equals_style: bool,
    desc: String,
    enabled: bool,
    value: String,
}

#[derive(Clone)]
struct Parsed {
    opts: Vec<HelpOpt>,
    subs: Vec<(String, String)>,
}

enum Stage {
    Choose,
    Loading(mpsc::Receiver<Result<Parsed, String>>),
    Form(Parsed),
}

/// Rows in the form view: subcommands, then options, then extra + actions.
enum FormRow {
    Sub(usize),
    Opt(usize),
    Extra,
    RunTerminal,
    RunDetached,
    PinWithArgs,
}

pub struct AppLauncher {
    path: PathBuf,
    stage: Stage,
    sel: usize,
    scroll: usize,
    subpath: Vec<String>,
    extra: String,
    editing: bool,
    status: String,
    t: u64,
}

impl AppLauncher {
    pub fn new(path: PathBuf) -> Self {
        AppLauncher {
            path,
            stage: Stage::Choose,
            sel: 0,
            scroll: 0,
            subpath: Vec::new(),
            extra: String::new(),
            editing: false,
            status: String::new(),
            t: 0,
        }
    }

    fn parse_help(&mut self) {
        let (tx, rx) = mpsc::channel();
        let path = self.path.clone();
        let subpath = self.subpath.clone();
        std::thread::spawn(move || {
            let _ = tx.send(run_help(&path, &subpath));
        });
        self.stage = Stage::Loading(rx);
        self.sel = 0;
        self.scroll = 0;
    }

    fn launch_detached(&mut self) {
        #[cfg(windows)]
        {
            use std::os::windows::process::CommandExt;
            const CREATE_NEW_CONSOLE: u32 = 0x0000_0010;
            let ext = self
                .path
                .extension()
                .and_then(|e| e.to_str())
                .unwrap_or("")
                .to_ascii_lowercase();
            let args = self.collected_args();
            let result = if matches!(ext.as_str(), "bat" | "cmd" | "ps1") {
                let mut c = Command::new("cmd.exe");
                c.arg("/c").arg("start").arg("").arg(&self.path).args(&args);
                c.creation_flags(CREATE_NEW_CONSOLE).spawn()
            } else {
                let mut c = Command::new(&self.path);
                if let Some(dir) = self.path.parent() {
                    c.current_dir(dir);
                }
                c.args(&args).creation_flags(CREATE_NEW_CONSOLE).spawn()
            };
            match result {
                Ok(_) => self.status = "🚀 launched detached".into(),
                Err(e) => self.status = format!("✗ {e}"),
            }
        }
        #[cfg(not(windows))]
        {
            use std::os::unix::process::CommandExt;
            use std::process::Stdio;
            let args = self.collected_args();
            let is_app_bundle = cfg!(target_os = "macos")
                && self
                    .path
                    .extension()
                    .and_then(|e| e.to_str())
                    .map(|e| e.eq_ignore_ascii_case("app"))
                    .unwrap_or(false);
            let result = if is_app_bundle {
                // Launch .app bundles through LaunchServices
                let mut c = Command::new("open");
                c.arg(&self.path);
                if !args.is_empty() {
                    c.arg("--args").args(&args);
                }
                c.stdin(Stdio::null())
                    .stdout(Stdio::null())
                    .stderr(Stdio::null())
                    .spawn()
            } else {
                let mut c = Command::new(&self.path);
                if let Some(dir) = self.path.parent() {
                    c.current_dir(dir);
                }
                c.args(&args)
                    .process_group(0)
                    .stdin(Stdio::null())
                    .stdout(Stdio::null())
                    .stderr(Stdio::null())
                    .spawn()
            };
            match result {
                Ok(_) => self.status = "🚀 launched detached".into(),
                Err(e) => self.status = format!("✗ {e}"),
            }
        }
    }

    fn collected_args(&self) -> Vec<String> {
        let mut args = self.subpath.clone();
        if let Stage::Form(p) = &self.stage {
            for o in &p.opts {
                if !o.enabled {
                    continue;
                }
                if o.takes_value {
                    if o.value.is_empty() {
                        continue;
                    }
                    if o.equals_style {
                        args.push(format!("{}={}", o.flag, o.value));
                    } else {
                        args.push(o.flag.clone());
                        args.push(o.value.clone());
                    }
                } else {
                    args.push(o.flag.clone());
                }
            }
        }
        args.extend(self.extra.split_whitespace().map(|s| s.to_string()));
        args
    }

    fn form_rows(p: &Parsed) -> Vec<FormRow> {
        let mut rows = Vec::new();
        for i in 0..p.subs.len() {
            rows.push(FormRow::Sub(i));
        }
        for i in 0..p.opts.len() {
            rows.push(FormRow::Opt(i));
        }
        rows.push(FormRow::Extra);
        rows.push(FormRow::RunTerminal);
        rows.push(FormRow::RunDetached);
        rows.push(FormRow::PinWithArgs);
        rows
    }

    /// Pre-filled pin for this program; args tokens with spaces get quoted.
    fn pin_with_args(&self) -> PinnedApp {
        let mut pin = PinnedApp::from_path(self.path.clone());
        pin.args = self
            .collected_args()
            .iter()
            .map(|a| {
                if a.chars().any(char::is_whitespace) {
                    format!("\"{a}\"")
                } else {
                    a.clone()
                }
            })
            .collect::<Vec<_>>()
            .join(" ");
        pin
    }

    fn name(&self) -> String {
        self.path
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_else(|| self.path.to_string_lossy().to_string())
    }
}

fn run_help(path: &PathBuf, subpath: &[String]) -> Result<Parsed, String> {
    let mut cmd = Command::new(path);
    cmd.args(subpath).arg("--help");
    if let Some(dir) = path.parent() {
        cmd.current_dir(dir);
    }
    let (tx, rx) = mpsc::channel();
    let handle = std::thread::spawn(move || {
        let _ = tx.send(cmd.output());
    });
    let output = match rx.recv_timeout(Duration::from_secs(6)) {
        Ok(Ok(o)) => o,
        Ok(Err(e)) => return Err(format!("cannot run --help: {e}")),
        Err(_) => return Err("--help timed out (interactive program?)".into()),
    };
    let _ = handle.join();
    let mut text = String::from_utf8_lossy(&output.stdout).to_string();
    if text.trim().is_empty() {
        text = String::from_utf8_lossy(&output.stderr).to_string();
    }
    if text.trim().is_empty() {
        return Err("no --help output — use extra args or run directly".into());
    }
    Ok(parse_help_text(&text))
}

fn parse_help_text(text: &str) -> Parsed {
    let mut opts: Vec<HelpOpt> = Vec::new();
    let mut subs: Vec<(String, String)> = Vec::new();
    let mut in_commands = false;

    for raw in text.lines() {
        let line = raw.trim_end();
        let trimmed = line.trim_start();
        let lower = trimmed.to_ascii_lowercase();

        if lower.starts_with("commands") || lower.starts_with("subcommands") {
            in_commands = true;
            continue;
        }
        if trimmed.is_empty() {
            continue;
        }
        // a new section header ends the commands block
        if in_commands && !raw.starts_with(' ') && trimmed.ends_with(':') {
            in_commands = false;
        }

        if trimmed.starts_with('-') {
            in_commands = false;
            // split flags part from description (2+ spaces gap)
            let (flag_part, desc) = match trimmed.find("  ") {
                Some(i) => (&trimmed[..i], trimmed[i..].trim().to_string()),
                None => (trimmed, String::new()),
            };
            // choose the long flag if present, else the short one
            let mut best: Option<String> = None;
            let mut takes_value = false;
            let mut equals_style = false;
            for tok in flag_part.split(|c| c == ',' || c == ' ') {
                let tok = tok.trim();
                if tok.is_empty() {
                    continue;
                }
                if tok.starts_with("--") {
                    let mut flag = tok.to_string();
                    if let Some(eq) = tok.find('=') {
                        flag = tok[..eq].to_string();
                        takes_value = true;
                        equals_style = true;
                    }
                    if let Some(lt) = flag.find('<') {
                        flag = flag[..lt].to_string();
                        takes_value = true;
                    }
                    let flag = flag.trim_matches(|c: char| c == '[' || c == ']').to_string();
                    best = Some(flag);
                } else if tok.starts_with('-') && best.is_none() && tok.len() >= 2 {
                    best = Some(tok.trim_matches(|c: char| c == '[' || c == ']').to_string());
                } else if !tok.starts_with('-')
                    && (tok.starts_with('<')
                        || tok.chars().all(|c| c.is_ascii_uppercase() || c == '_'))
                    && tok.len() > 1
                {
                    takes_value = true;
                }
            }
            if let Some(flag) = best {
                if flag.len() > 1 && !opts.iter().any(|o| o.flag == flag) && opts.len() < 40 {
                    opts.push(HelpOpt {
                        flag,
                        takes_value,
                        equals_style,
                        desc: desc.chars().take(80).collect(),
                        enabled: false,
                        value: String::new(),
                    });
                }
            }
        } else if in_commands && raw.starts_with(' ') {
            let mut parts = trimmed.splitn(2, char::is_whitespace);
            if let Some(name) = parts.next() {
                let clean: String = name.trim_matches(',').to_string();
                if !clean.is_empty()
                    && clean
                        .chars()
                        .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == ':')
                    && !clean.chars().next().unwrap().is_ascii_digit()
                    && subs.len() < 40
                    && !subs.iter().any(|(n, _)| n == &clean)
                {
                    let desc = parts.next().unwrap_or("").trim().chars().take(70).collect();
                    subs.push((clean, desc));
                }
            }
        }
    }
    Parsed { opts, subs }
}

impl AppWindow for AppLauncher {
    fn title(&self) -> String {
        format!("Launch {}", self.name())
    }

    fn render(&mut self, f: &mut Frame, area: Rect, _focused: bool) {
        if area.height < 4 {
            return;
        }
        let accent = Style::default()
            .fg(Color::Rgb(0, 190, 255))
            .add_modifier(Modifier::BOLD);
        let dim = Style::default().fg(Color::Rgb(140, 150, 175));
        let txt = Style::default().fg(Color::Rgb(215, 218, 230));
        let sel_style = Style::default()
            .fg(Color::White)
            .bg(Color::Rgb(0, 96, 150))
            .add_modifier(Modifier::BOLD);

        let mut lines: Vec<Line> = Vec::new();
        match &self.stage {
            Stage::Choose => {
                lines.push(Line::default());
                lines.push(Line::from(Span::styled(
                    format!("   ⚙ {}", self.name()),
                    accent,
                )));
                lines.push(Line::from(Span::styled(
                    format!("   {}", self.path.to_string_lossy()),
                    dim,
                )));
                lines.push(Line::default());
                let choices = [
                    "🖥  Run in terminal window",
                    "🧩  Configure arguments (--help form)",
                    "🚀  Launch detached (own OS window)",
                    "📌  Pin to desktop / taskbar…",
                ];
                for (i, c) in choices.iter().enumerate() {
                    let style = if i == self.sel { sel_style } else { txt };
                    lines.push(Line::from(Span::styled(format!("     {c}  "), style)));
                    lines.push(Line::default());
                }
            }
            Stage::Loading(_) => {
                let spin = SPINNER[(self.t / 2) as usize % SPINNER.len()];
                lines.push(Line::default());
                lines.push(Line::from(Span::styled(
                    format!("   {spin}  reading {} {} --help …", self.name(), self.subpath.join(" ")),
                    accent,
                )));
            }
            Stage::Form(p) => {
                let rows = Self::form_rows(p);
                let header = if self.subpath.is_empty() {
                    format!("   ⚙ {}  — toggle options, then run", self.name())
                } else {
                    format!("   ⚙ {} {}  — Bksp goes up", self.name(), self.subpath.join(" "))
                };
                lines.push(Line::from(Span::styled(header, accent)));
                lines.push(Line::default());

                let list_h = area.height.saturating_sub(3) as usize;
                if self.sel < self.scroll {
                    self.scroll = self.sel;
                }
                if self.sel >= self.scroll + list_h {
                    self.scroll = self.sel + 1 - list_h;
                }
                for (i, row) in rows.iter().enumerate().skip(self.scroll).take(list_h) {
                    let selected = i == self.sel;
                    let style = if selected { sel_style } else { txt };
                    let line = match row {
                        FormRow::Sub(s) => {
                            let (name, desc) = &p.subs[*s];
                            Line::from(vec![
                                Span::styled(format!("   ▸ {name:<18}"), style),
                                Span::styled(desc.clone(), if selected { style } else { dim }),
                            ])
                        }
                        FormRow::Opt(o) => {
                            let opt = &p.opts[*o];
                            let mark = if opt.enabled { "☑" } else { "☐" };
                            let val = if opt.takes_value {
                                if self.editing && selected {
                                    format!(" = {}▏", opt.value)
                                } else {
                                    format!(" = {}", opt.value)
                                }
                            } else {
                                String::new()
                            };
                            Line::from(vec![
                                Span::styled(format!("   {mark} {}{val}", opt.flag), style),
                                Span::styled(format!("  {}", opt.desc), if selected { style } else { dim }),
                            ])
                        }
                        FormRow::Extra => {
                            let cursor = if self.editing && selected { "▏" } else { "" };
                            Line::from(Span::styled(
                                format!("   ✎ extra args: {}{cursor}", self.extra),
                                style,
                            ))
                        }
                        FormRow::RunTerminal => {
                            Line::from(Span::styled("   ▶ Run in terminal", style))
                        }
                        FormRow::RunDetached => {
                            Line::from(Span::styled("   🚀 Run detached", style))
                        }
                        FormRow::PinWithArgs => {
                            Line::from(Span::styled("   📌 Pin with these args…", style))
                        }
                    };
                    lines.push(line);
                }
            }
        }
        f.render_widget(
            Paragraph::new(lines),
            Rect::new(area.x, area.y, area.width, area.height.saturating_sub(1)),
        );

        let hint = match &self.stage {
            Stage::Choose => " ↑↓ choose · Enter select · Esc close ",
            Stage::Loading(_) => " Esc cancel ",
            Stage::Form(_) => " Space toggle · Enter edit/run · Bksp back · Esc close ",
        };
        f.render_widget(
            Paragraph::new(Span::styled(
                format!(" {}  │{}", self.status, hint),
                Style::default().fg(Color::Rgb(140, 150, 175)).bg(Color::Rgb(18, 22, 36)),
            ))
            .style(Style::default().bg(Color::Rgb(18, 22, 36))),
            Rect::new(area.x, area.y + area.height - 1, area.width, 1),
        );
    }

    fn on_key(&mut self, k: KeyEvent) -> Action {
        self.status.clear();
        match &mut self.stage {
            Stage::Choose => match k.code {
                KeyCode::Up => self.sel = self.sel.checked_sub(1).unwrap_or(3),
                KeyCode::Down => self.sel = (self.sel + 1) % 4,
                KeyCode::Enter => match self.sel {
                    0 => {
                        return Action::Launch(Launch::Terminal {
                            program: Some(self.path.clone()),
                            args: Vec::new(),
                            cwd: None,
                        })
                    }
                    1 => self.parse_help(),
                    2 => {
                        self.launch_detached();
                        if self.status.starts_with('🚀') {
                            return Action::Close;
                        }
                    }
                    _ => {
                        return Action::LaunchAndClose(Launch::PinEditor {
                            pin: PinnedApp::from_path(self.path.clone()),
                            to: PinTo::Desktop,
                            edit: None,
                        })
                    }
                },
                KeyCode::Esc => return Action::Close,
                _ => {}
            },
            Stage::Loading(_) => {
                if k.code == KeyCode::Esc {
                    self.stage = Stage::Choose;
                }
            }
            Stage::Form(p) => {
                let rows = Self::form_rows(p);
                let cur = rows.get(self.sel);
                if self.editing {
                    let target: Option<&mut String> = match cur {
                        Some(FormRow::Opt(o)) => Some(&mut p.opts[*o].value),
                        Some(FormRow::Extra) => Some(&mut self.extra),
                        _ => None,
                    };
                    if let Some(target) = target {
                        match k.code {
                            KeyCode::Esc | KeyCode::Enter => self.editing = false,
                            KeyCode::Backspace => {
                                target.pop();
                            }
                            KeyCode::Char(c) => target.push(c),
                            _ => {}
                        }
                        return Action::None;
                    }
                    self.editing = false;
                }
                match k.code {
                    KeyCode::Up => self.sel = self.sel.saturating_sub(1),
                    KeyCode::Down => self.sel = (self.sel + 1).min(rows.len().saturating_sub(1)),
                    KeyCode::Char(' ') => {
                        if let Some(FormRow::Opt(o)) = cur {
                            p.opts[*o].enabled = !p.opts[*o].enabled;
                        }
                    }
                    KeyCode::Enter => match cur {
                        Some(FormRow::Sub(s)) => {
                            self.subpath.push(p.subs[*s].0.clone());
                            self.parse_help();
                        }
                        Some(FormRow::Opt(o)) => {
                            if p.opts[*o].takes_value {
                                p.opts[*o].enabled = true;
                                self.editing = true;
                            } else {
                                p.opts[*o].enabled = !p.opts[*o].enabled;
                            }
                        }
                        Some(FormRow::Extra) => self.editing = true,
                        Some(FormRow::RunTerminal) => {
                            return Action::Launch(Launch::Terminal {
                                program: Some(self.path.clone()),
                                args: self.collected_args(),
                                cwd: None,
                            });
                        }
                        Some(FormRow::RunDetached) => {
                            self.launch_detached();
                        }
                        Some(FormRow::PinWithArgs) => {
                            return Action::LaunchAndClose(Launch::PinEditor {
                                pin: self.pin_with_args(),
                                to: PinTo::Desktop,
                                edit: None,
                            });
                        }
                        None => {}
                    },
                    KeyCode::Backspace => {
                        if self.subpath.pop().is_some() {
                            self.parse_help();
                        } else {
                            self.stage = Stage::Choose;
                            self.sel = 0;
                        }
                    }
                    KeyCode::Esc => return Action::Close,
                    _ => {}
                }
            }
        }
        Action::None
    }

    fn on_mouse(&mut self, m: MouseEvent, area: Rect) -> Action {
        if let MouseEventKind::Down(MouseButton::Left) = m.kind {
            match &self.stage {
                Stage::Choose => {
                    // choice rows are at offsets 4, 6, 8, 10 from area top
                    let rel = m.row.saturating_sub(area.y);
                    for (i, y) in [4u16, 6, 8, 10].iter().enumerate() {
                        if rel == *y {
                            self.sel = i;
                            return self.on_key(KeyEvent::from(KeyCode::Enter));
                        }
                    }
                }
                Stage::Form(_) => {
                    let rel = m.row.saturating_sub(area.y);
                    if rel >= 2 {
                        let idx = self.scroll + (rel - 2) as usize;
                        if let Stage::Form(p) = &self.stage {
                            if idx < Self::form_rows(p).len() {
                                if idx == self.sel {
                                    return self.on_key(KeyEvent::from(KeyCode::Enter));
                                }
                                self.sel = idx;
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        Action::None
    }

    fn on_tick(&mut self) {
        self.t += 1;
        if let Stage::Loading(rx) = &self.stage {
            match rx.try_recv() {
                Ok(Ok(parsed)) => {
                    self.stage = Stage::Form(parsed);
                    self.sel = 0;
                    self.scroll = 0;
                }
                Ok(Err(e)) => {
                    self.status = format!("✗ {e}");
                    self.subpath.pop();
                    self.stage = Stage::Choose;
                }
                Err(mpsc::TryRecvError::Empty) => {}
                Err(mpsc::TryRecvError::Disconnected) => self.stage = Stage::Choose,
            }
        }
    }
}
